source=P/'art_source/a13_first_tree_source/source-group-contract.json';c=json.loads(source.read_text());g=json.loads((D/'geometry-diagnostic.json').read_text());s=g['registration']['scale'];t=np.array(g['registration']['raw_world_origin']);raw=np.array(Image.open(D/'raw.png').convert('RGBA'));h,w=raw.shape[:2];x=t[0]+(np.arange(w)+.5)*s;cells=np.clip(np.floor(x/48).astype(int),55,61);stored=np.any(raw!=0,axis=2);rebuilt=np.zeros_like(raw);count=np.zeros((h,w),np.uint8);entries=[]
